begin read only; set local statement_timeout='5s'; set local lock_timeout='1s'; select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_object('column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull)) from pg_attribute a where a.attrelid='public.component_internal'::regclass and a.attnum>0 and not a.attisdropped),'rls',(select relrowsecurity from pg_class where oid='public.component_internal'::regclass),'anonSelect',has_table_privilege('anon','public.component_internal','SELECT'),'authenticatedSelect',has_table_privilege('authenticated','public.component_internal','SELECT'),'policies',(select jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check)) from pg_policies where schemaname='public' and tablename='component_internal')) as metadata limit 1; commit;
